mapper.select:
SELECT speciality.*, college.name AS collegeName FROM speciality LEFT JOIN college ON speciality.college_id = college.id WHERE speciality.college_id = #{collegeId}
AND speciality.name LIKE CONCAT('%', #{name}, '%')
ORDER BY speciality.id ASC

mapper.update:
UPDATE speciality
SET name = #{name},
    college_id = #{collegeId},
    content = #{content}
WHERE id = #{id}
